import { HttpClient } from "@angular/common/http";
import { inject, Injectable } from "@angular/core";
import { catchError, finalize, tap, throwError } from "rxjs";

import { User } from "src/app/store/userStore";
import { environment } from "src/environments/environment.development";
import { NotificationService } from "src/app/shared/services/notification.service";
import { OptimisticService } from "src/app/shared/services/optimistic.service";

@Injectable({
  providedIn: "root",
})
export class AdmUserService {
  constructor() {}

  private http = inject(HttpClient);
  private optimisicService = inject(OptimisticService);
  private notificationService = inject(NotificationService);

  fetchUsers() {
    return this.http.get<User[]>(`${environment.apiUrl}/user`);
  }

  addUser(user: User) {
    this.optimisicService.setLoadingState(user.id, {
      isLoading: true,
      operation: "creating",
    });

    this.notificationService.showToast(
      "info",
      `${user.username}`,
      "Creando usuario",
    );
    return this.http
      .post<User>(`${environment.apiUrl}/auth/register`, user)
      .pipe(
        tap(() => {
          this.notificationService.showToast(
            "success",
            `${user.username}`,
            "Usuario creado",
          );
        }),
        catchError((error) => {
          this.notificationService.showToast(
            "error",
            `${user.username}`,
            "Error creando usuario",
          );
          return throwError(() => error);
        }),
        finalize(() => {
          this.optimisicService.setLoadingState(user.id, { isLoading: false });
        }),
      );
  }

  updateUser(user: Omit<User, "token" | "password">) {
    this.optimisicService.setLoadingState(user.id, {
      isLoading: true,
      operation: "updating",
    });

    this.notificationService.showToast(
      "info",
      `${user.username}`,
      "Actualizando usuario",
    );

    return this.http
      .patch<User>(`${environment.apiUrl}/users/${user.id}`, user)
      .pipe(
        tap(() => {
          this.notificationService.showToast(
            "success",
            `${user.username}`,
            "Usuario actualizado",
          );
        }),
        catchError((error) => {
          this.notificationService.showToast(
            "error",
            `${user.username}`,
            "Error actualizando usuario",
          );
          return throwError(() => error);
        }),
        finalize(() => {
          this.optimisicService.setLoadingState(user.id, { isLoading: false });
        }),
      );
  }

  deleteUser(user: User) {
    this.optimisicService.setLoadingState(user.id, {
      isLoading: true,
      operation: "deleting",
    });

    this.notificationService.showToast(
      "info",
      `${user.username}`,
      "Eliminando usuario",
    );

    return this.http.delete(`${environment.apiUrl}/users/${user.id}`).pipe(
      tap(() => {
        this.notificationService.showToast(
          "success",
          `${user.username}`,
          "Usuario eliminado",
        );
      }),
      catchError((error) => {
        this.notificationService.showToast(
          "error",
          `${user.username}`,
          "Error eliminando usuario",
        );
        return throwError(() => error);
      }),
      finalize(() => {
        this.optimisicService.setLoadingState(user.id, { isLoading: false });
      }),
    );
  }

  getToken() {
    return localStorage.getItem("token");
  }
}
